insert into public.recipe_steps (recipe_id,position,instruction,timer_seconds,image_path) values ('10000000-0000-4000-8000-000000000035'::uuid,0,'Faire chauffer l’huile dans un wok ou une poêle profonde. Faire revenir le bœuf haché jusqu’à ce qu’il soit bien émietté et légèrement croustillant.',null,null);
insert into public.recipe_steps (recipe_id,position,instruction,timer_seconds,image_path) values ('10000000-0000-4000-8000-000000000035'::uuid,1,'Ajouter ail, gingembre, doubanjiang, douchi et piment. Cuire 1 à 2 minutes jusqu’à ce que l’huile devienne rouge et très parfumée.',null,null);
insert into public.recipe_steps (recipe_id,position,instruction,timer_seconds,image_path) values ('10000000-0000-4000-8000-000000000035'::uuid,2,'Verser le bouillon, la sauce soja et le vin de riz. Porter à frémissement puis ajouter délicatement les cubes de tofu.',null,null);
insert into public.recipe_steps (recipe_id,position,instruction,timer_seconds,image_path) values ('10000000-0000-4000-8000-000000000035'::uuid,3,'Laisser mijoter 6 à 8 minutes sans briser le tofu. Ajouter la fécule diluée pour épaissir légèrement la sauce.',null,null);
insert into public.recipe_steps (recipe_id,position,instruction,timer_seconds,image_path) values ('10000000-0000-4000-8000-000000000035'::uuid,4,'Ajouter environ la moitié du poivre du Sichuan et une partie des oignons verts. Mélanger très délicatement.',null,null);
insert into public.recipe_steps (recipe_id,position,instruction,timer_seconds,image_path) values ('10000000-0000-4000-8000-000000000035'::uuid,5,'Servir brûlant, saupoudré du reste de poivre du Sichuan et d’oignons verts, afin de correspondre à la photo de référence.',null,null);
insert into public.recipe_steps (recipe_id,position,instruction,timer_seconds,image_path) values ('10000000-0000-4000-8000-000000000036'::uuid,0,'Mettre le poulet, l’ail, les grains de poivre, la sauce soja et le vinaigre dans une casserole. Porter à ébullition puis réduire immédiatement.',null,null);
insert into public.recipe_steps (recipe_id,position,instruction,timer_seconds,image_path) values ('10000000-0000-4000-8000-000000000036'::uuid,1,'Ajouter le laurier et l’eau. Couvrir partiellement et laisser mijoter environ 25 minutes.',null,null);
insert into public.recipe_steps (recipe_id,position,instruction,timer_seconds,image_path) values ('10000000-0000-4000-8000-000000000036'::uuid,2,'Retirer le poulet et le faire dorer dans une poêle avec un peu d’huile.',null,null);
insert into public.recipe_steps (recipe_id,position,instruction,timer_seconds,image_path) values ('10000000-0000-4000-8000-000000000036'::uuid,3,'Pendant ce temps, réduire le liquide de cuisson jusqu’à obtenir une sauce brillante et concentrée. Remettre le poulet dans la sauce et l’enrober.',null,null);
insert into public.recipe_steps (recipe_id,position,instruction,timer_seconds,image_path) values ('10000000-0000-4000-8000-000000000036'::uuid,4,'Cuire le riz blanc séparément puis le répartir dans les assiettes.',null,null);
insert into public.recipe_steps (recipe_id,position,instruction,timer_seconds,image_path) values ('10000000-0000-4000-8000-000000000036'::uuid,5,'Déposer le poulet adobo sur le riz, napper de sauce et finir avec les oignons verts visibles sur la photo.',null,null);
insert into public.recipe_steps (recipe_id,position,instruction,timer_seconds,image_path) values ('10000000-0000-4000-8000-000000000037'::uuid,0,'Mixer tomates, poivrons, piments et deux oignons jusqu’à obtenir une purée lisse.',null,null);
insert into public.recipe_steps (recipe_id,position,instruction,timer_seconds,image_path) values ('10000000-0000-4000-8000-000000000037'::uuid,1,'Faire revenir le dernier oignon haché dans l’huile. Ajouter le concentré de tomate et cuire 3 à 4 minutes.',null,null);
insert into public.recipe_steps (recipe_id,position,instruction,timer_seconds,image_path) values ('10000000-0000-4000-8000-000000000037'::uuid,2,'Ajouter la purée de légumes et laisser réduire jusqu’à ce que la sauce épaississe nettement et perde son goût cru.',null,null);
insert into public.recipe_steps (recipe_id,position,instruction,timer_seconds,image_path) values ('10000000-0000-4000-8000-000000000037'::uuid,3,'Ajouter bouillon, thym, curry, laurier, gingembre, ail et sel. Porter à ébullition.',null,null);
insert into public.recipe_steps (recipe_id,position,instruction,timer_seconds,image_path) values ('10000000-0000-4000-8000-000000000037'::uuid,4,'Ajouter le riz rincé. Couvrir hermétiquement et cuire à feu très doux jusqu’à absorption presque complète et riz tendre, environ 30 à 40 minutes.',null,null);
insert into public.recipe_steps (recipe_id,position,instruction,timer_seconds,image_path) values ('10000000-0000-4000-8000-000000000037'::uuid,5,'Aérer doucement le riz à la fourchette et servir tel quel, sans garniture extérieure, pour correspondre à la photo de référence.',null,null);
insert into public.recipe_steps (recipe_id,position,instruction,timer_seconds,image_path) values ('10000000-0000-4000-8000-000000000038'::uuid,0,'Dessaler la morue à l’avance en changeant l’eau plusieurs fois. La pocher doucement, retirer peau et arêtes puis l’effilocher.',null,null);
insert into public.recipe_steps (recipe_id,position,instruction,timer_seconds,image_path) values ('10000000-0000-4000-8000-000000000038'::uuid,1,'Frire les pommes de terre allumettes jusqu’à ce qu’elles soient juste dorées et croustillantes. Égoutter soigneusement.',null,null);
insert into public.recipe_steps (recipe_id,position,instruction,timer_seconds,image_path) values ('10000000-0000-4000-8000-000000000038'::uuid,2,'Faire fondre doucement les oignons dans l’huile d’olive sans les colorer. Ajouter la morue et mélanger 2 à 3 minutes.',null,null);
insert into public.recipe_steps (recipe_id,position,instruction,timer_seconds,image_path) values ('10000000-0000-4000-8000-000000000038'::uuid,3,'Ajouter les pommes de terre et mélanger. Verser les œufs battus et cuire à feu doux en remuant jusqu’à ce qu’ils soient crémeux mais pris.',null,null);
insert into public.recipe_steps (recipe_id,position,instruction,timer_seconds,image_path) values ('10000000-0000-4000-8000-000000000038'::uuid,4,'Poivrer et goûter avant d’ajouter du sel.',null,null);
insert into public.recipe_steps (recipe_id,position,instruction,timer_seconds,image_path) values ('10000000-0000-4000-8000-000000000038'::uuid,5,'Servir immédiatement avec les olives noires réparties sur le dessus et le persil haché, comme sur la photo de référence.',null,null);
