values ('10000000-0000-4000-8000-000000000035'::uuid,'ac515660-4852-4ebd-8cb5-3348d60e06e9'::uuid,'Mapo tofu de Chengdu','mapo-tofu-chengdu','Tofu tendre dans une sauce rouge pimentée au doubanjiang avec viande hachée, ail, gingembre, poivre du Sichuan et oignons verts.','Le classique du Sichuan : tofu, viande hachée et sauce málà.','fr','CN','Chengdu, Sichuan','Tofu épicé','adapted'::public.recipe_authenticity,'published'::public.recipe_status,'medium'::public.recipe_difficulty,20,20,4.00,now(),(select id from public.culinary_places where slug='cn-chengdu'),true,'Wikibooks Cookbook','https://en.wikibooks.org/wiki/Cookbook:Mapo_Tofu','Version éditoriale réécrite à partir de la recette libre Wikibooks. L’association au Sichuan/Chengdu est documentée séparément; la photo retenue est prise à Chengdu et montre tofu, viande, sauce rouge et oignons verts.')
