values ('10000000-0000-4000-8000-000000000036'::uuid,'ac515660-4852-4ebd-8cb5-3348d60e06e9'::uuid,'Chicken adobo philippin avec riz','chicken-adobo-philippin','Poulet philippin braisé au vinaigre, sauce soja, ail, laurier et grains de poivre, servi sur riz blanc et fini aux oignons verts.','Poulet braisé vinaigre-soja avec ail, laurier, poivre et riz.','fr','PH','Philippines','Poulet braisé','adapted'::public.recipe_authenticity,'published'::public.recipe_status,'easy'::public.recipe_difficulty,15,45,4.00,now(),(select id from public.culinary_places where slug='ph'),true,'Wikibooks Cookbook','https://en.wikibooks.org/wiki/Cookbook:Adobo_Chicken_(Philippine)','Version éditoriale réécrite d’une recette libre Wikibooks. Le riz est prévu par la source; les oignons verts sont ajoutés uniquement pour correspondre à la photo choisie.')
