values ('10000000-0000-4000-8000-000000000035'::uuid,'external_licensed'::public.media_source_type,'ready'::public.media_status,null,'https://upload.wikimedia.org/wikipedia/commons/8/88/Chen_Mapo_Tofu.jpg',null,'Mapo tofu photographié à Chengdu avec tofu, viande, sauce pimentée et oignons verts',null,null,null,'Wikimedia Commons','https://commons.wikimedia.org/wiki/File:Chen_Mapo_Tofu.jpg','ZhengZhou','https://commons.wikimedia.org/wiki/user:ZhengZhou','CC BY-SA 4.0','https://creativecommons.org/licenses/by-sa/4.0/','Photo : ZhengZhou · Wikimedia Commons · CC BY-SA 4.0',null,null,true,true,'Photo géolocalisée à Chengdu. Les éléments visibles principaux — tofu, viande hachée, sauce rouge et oignons verts — sont inclus.',null);
values ('10000000-0000-4000-8000-000000000036'::uuid,'external_licensed'::public.media_source_type,'ready'::public.media_status,null,'https://upload.wikimedia.org/wikipedia/commons/d/df/Filipino_Chicken_Adobo.JPG',null,'Chicken adobo philippin servi sur riz blanc avec oignons verts',null,null,null,'Wikimedia Commons','https://commons.wikimedia.org/wiki/File:Filipino_Chicken_Adobo.JPG','CapitalCRUZ','https://commons.wikimedia.org/wiki/File:Filipino_Chicken_Adobo.JPG','CC BY-SA 3.0','https://creativecommons.org/licenses/by-sa/3.0/','Photo : CapitalCRUZ · Wikimedia Commons · CC BY-SA 3.0',null,null,true,true,'La photo montre poulet adobo, riz blanc et oignons verts; ces trois éléments sont présents dans la recette.',null);
values ('10000000-0000-4000-8000-000000000037'::uuid,'external_licensed'::public.media_source_type,'ready'::public.media_status,null,'https://upload.wikimedia.org/wikipedia/commons/6/67/Nigerian_jollof_rice.jpg',null,'Jollof rice nigérian sans accompagnement extérieur',null,null,null,'Wikimedia Commons','https://commons.wikimedia.org/wiki/File:Nigerian_jollof_rice.jpg','Halima Waziri','https://commons.wikimedia.org/wiki/User:Halima_Waziri','CC BY-SA 4.0','https://creativecommons.org/licenses/by-sa/4.0/','Photo : Halima Waziri · Wikimedia Commons · CC BY-SA 4.0',null,null,true,true,'Photo prise au Nigeria. Elle montre essentiellement le riz jollof lui-même; aucun accompagnement visible supplémentaire à reproduire.',null);
